from pathlib import Path
root=Path(__file__).parent
css=r'''
:root{--ink:#183d35;--muted:#465e54;--soft:#5d7268;--line:#73857a;--hair:#cdd6cc;--green:#315e49;--amber:#80633c;--paper:#fffffc;--field:#eff1ec;--wash:#e1e8db}
*{box-sizing:border-box}html,body{margin:0;background:var(--field);color:var(--ink);font:400 16px/1.5 'CasePath Instrument',Arial,sans-serif;-webkit-font-smoothing:antialiased}button,select{font:inherit;color:inherit}button{cursor:pointer}button:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid var(--green);outline-offset:4px}button.link{padding:0;border:0;background:none;text-align:left}button.link:hover{text-decoration:underline;text-underline-offset:3px}.top{height:56px;display:flex;align-items:center;gap:24px;padding:0 36px;border-bottom:1px solid var(--line)}.brand{font-size:22px;font-weight:600}.tag,.nav{color:var(--muted);font-size:14px}.nav{margin-left:auto;display:flex;gap:26px}.nav .selected{color:var(--ink);border-bottom:2px solid var(--ink)}.case{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:32px;padding:20px 36px 16px;border-bottom:1px solid var(--hair);align-items:end}.eyebrow,.col h2{font-size:12px;font-weight:500;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}h1{margin:4px 0;font-size:25px;line-height:1.3;font-weight:500;letter-spacing:-.01em}.asks{font-size:16px;color:var(--muted);max-width:800px}.asks q{color:var(--ink)}.controls{display:flex;gap:16px;align-items:center;margin-top:12px;font-size:13px;color:var(--muted)}.controls button,.controls select{border:0;border-bottom:1px solid var(--hair);background:transparent;padding:0 0 2px}.controls .fiction{margin-left:auto}.tally{display:flex;gap:25px}.metric{flex:none}.controls select{max-width:370px;min-width:0}.metric .n{font-size:31px;line-height:1;font-weight:500;font-variant-numeric:tabular-nums}.metric .l{margin-top:6px;font-size:12px;color:var(--muted)}main{display:grid;grid-template-columns:250px minmax(0,1fr) 405px;position:relative;min-height:590px}.col{padding:18px 28px 65px;min-width:0}.col+.col{border-left:1px solid var(--hair)}.col:first-child{padding-left:36px}.col:last-child{padding-right:36px}.col h2{margin:0 0 12px;display:flex;justify-content:space-between}.col h2 span{font-weight:400;text-transform:none;letter-spacing:0}.files{list-style:none;padding:0;margin:0}.files li{display:grid;grid-template-columns:14px minmax(0,1fr);gap:2px 10px;padding:11px 0;border-top:1px solid var(--hair)}.files li:last-child{border-bottom:1px solid var(--hair)}.files .nm{font-size:14.5px;line-height:1.45;color:var(--muted)}.files .mt{grid-column:2;font-size:12px;color:var(--muted)}.st-dot{width:10px;height:10px;border-radius:50%;border:1.5px solid var(--line);margin-top:6px;color:var(--green)}.read .st-dot{width:auto;height:auto;border:0;margin-top:0}.read .nm,.reading .nm{color:var(--ink)}.reading .st-dot{background:var(--green);border-color:var(--green)}.role{display:flex;gap:10px;align-items:baseline;font-size:18px;min-height:29px}.badge{font-size:12px;border:1px solid var(--green);color:var(--green);border-radius:3px;padding:1px 8px;white-space:nowrap}.doc{margin-top:12px;background:var(--paper);border:1px solid var(--line);height:365px;display:flex;flex-direction:column}.doc .name{font-size:12.5px;color:var(--muted);padding:12px 22px 8px;border-bottom:1px solid var(--hair);flex:none}.doc .scroll{overflow:auto;padding:14px 22px 20px;flex:1;min-height:0;scrollbar-width:thin}.doc .text{white-space:pre-wrap;font-size:16px;line-height:1.7}mark{background:var(--wash);color:inherit;box-shadow:inset 0 -2px var(--green)}.found{margin-top:12px;min-height:48px;font-size:15px;color:var(--muted)}.found b{color:var(--ink);font-weight:500}.found .feed{display:block;font-size:13px;margin-top:3px}.reuse{font-size:12.5px;color:var(--green);margin:-3px 0 14px}.graph{list-style:none;margin:0;padding:0}.node{position:relative;padding:0 0 17px 29px}.node::before{content:'';position:absolute;left:6px;top:20px;bottom:0;width:1.5px;background:var(--hair)}.node:last-child::before,.node:last-child .fill{display:none}.fill{position:absolute;left:6px;top:20px;bottom:0;width:1.5px;background:var(--green);transform:scaleY(0);transform-origin:top}.done .fill{transform:scaleY(1)}.node .c{position:absolute;left:0;top:4px;width:14px;height:14px;border-radius:50%;border:1.5px dashed var(--line);background:var(--field);display:grid;place-items:center;font-size:10px;line-height:1;color:var(--paper)}.node.in .c{border-style:solid}.node.active .c{border-color:var(--green);box-shadow:0 0 0 4px rgb(116 155 99/.2)}.node.done .c{background:var(--green);border-color:var(--green)}.node .lb{font-size:15px;line-height:1.4;color:var(--soft)}.node.in .lb{color:var(--ink)}.node .ev{display:flex;flex-wrap:wrap;gap:3px 12px;margin-top:4px;font-size:12.5px;line-height:1.4;color:var(--muted)}.ev .ok{color:var(--green)}.law{font-size:12.5px;color:var(--muted);font-variant-numeric:tabular-nums}.result{margin-top:12px;background:var(--paper);border:1px solid var(--line);border-left:3px solid var(--green);padding:22px 26px}.result .lead{font-size:21px;line-height:1.4;margin:8px 0 16px;letter-spacing:-.01em}.tests{list-style:none;margin:4px 0 16px;padding:0}.tests li{display:grid;grid-template-columns:16px minmax(0,1fr) auto;gap:8px;padding:6px 0;border-top:1px solid var(--hair);font-size:14px;line-height:1.4}.tests .yes{color:var(--green)}.tests .no{color:var(--amber)}.open{margin:0 0 16px;padding-left:12px;border-left:2px solid var(--amber);color:var(--amber);font-size:15px;line-height:1.45}.actions{display:flex;align-items:center;gap:14px;font-size:12.5px;color:var(--muted)}.btn{border:1px solid var(--ink);padding:8px 14px;color:var(--ink);border-radius:2px;background:var(--paper);font-size:14px;white-space:nowrap}.why{font-size:13px;margin-top:12px;color:var(--muted)}.why summary{cursor:pointer}.why p{margin:8px 0}.back{margin-top:10px;font-size:13px}.thread{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible;z-index:2}.thread path{fill:none;stroke:var(--green);stroke-width:1.5;stroke-linecap:round;stroke-dasharray:1}.thread circle{fill:var(--green)}footer{position:fixed;inset:auto 0 0;height:42px;padding:0 36px;display:flex;align-items:center;gap:14px;background:var(--field);border-top:1px solid var(--hair);color:var(--muted);font-size:12px;z-index:3}.pips{display:flex;gap:6px}.pip{width:24px;height:3px;background:var(--hair)}.pip.done{background:var(--green)}.pip.now{background:var(--ink)}.prog{height:2px;background:var(--hair);flex:1;margin-left:14px}.prog i{display:block;height:2px;background:var(--green);transform-origin:left}.option-name{margin-left:auto}.files-note{margin-top:15px;font-size:12px;color:var(--muted)}dialog{max-width:680px;width:90%;max-height:80vh;overflow:auto;border:1px solid var(--line);padding:28px;background:var(--paper);color:var(--ink)}dialog::backdrop{background:rgb(24 61 53/.24)}dialog h2{font-size:22px;font-weight:500}dialog pre{white-space:pre-wrap;font:inherit}dialog button{float:right}.error{padding:36px;color:var(--amber)}[hidden]{display:none!important}
/* B: the document is the workspace; the process reads as its live margin. */
body[data-option=B] .case{grid-template-columns:minmax(0,1fr) auto}body[data-option=B] main{grid-template-columns:minmax(0,1fr) 390px;padding:0 36px;column-gap:36px}body[data-option=B] .files-col{grid-column:1/-1;grid-row:1;padding:15px 0 14px;border-bottom:1px solid var(--hair)}body[data-option=B] .files-col h2,body[data-option=B] .files-note{display:none}body[data-option=B] .files{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px}body[data-option=B] .files li{border:0;padding:0 20px 0 0;border-right:1px solid var(--hair)}body[data-option=B] .files li:last-child{border-right:0}body[data-option=B] .files .nm{font-size:13px}body[data-option=B] .read-col{grid-column:1;grid-row:2;border:0;padding:18px 0 60px}body[data-option=B] .process-col{grid-column:2;grid-row:2;border:0;padding:18px 0 60px 26px;border-left:1px solid var(--hair)}body[data-option=B] .doc{height:365px}body[data-option=B] .doc .scroll{padding:20px 46px}body[data-option=B] .doc .name{padding-left:46px}body[data-option=B] .doc .text{font-size:17px;line-height:1.8}body[data-option=B] .result{padding:22px 38px}body[data-option=B] .result .lead{font-size:23px;max-width:770px}body[data-option=B] .tests li{font-size:14px;padding:6px 0}body[data-option=B] .node{padding-bottom:15px}
/* C: the whole process is the timeline; source detail opens beneath it. */
body[data-option=C] .case{padding-top:16px;padding-bottom:14px}body[data-option=C] main{grid-template-columns:260px minmax(0,1fr);padding:0 36px;column-gap:30px}body[data-option=C] .process-col{grid-row:1;grid-column:1/-1;border:0;border-bottom:1px solid var(--hair);padding:16px 0 18px}body[data-option=C] .process-col h2{display:inline-block;margin:0 16px 12px 0}body[data-option=C] .process-col h2 span{margin-left:12px}body[data-option=C] .reuse{display:inline;font-size:12px}body[data-option=C] .graph{display:grid;grid-template-columns:repeat(var(--nodes),minmax(0,1fr));gap:22px}body[data-option=C] .node{padding:28px 0 0}body[data-option=C] .node .c{top:2px;left:0}body[data-option=C] .node::before{left:24px;right:0;top:8px;height:1.5px;width:auto;bottom:auto}body[data-option=C] .node .fill{left:24px;right:0;top:8px;height:1.5px;width:auto;bottom:auto;transform:scaleX(0);transform-origin:left}body[data-option=C] .node.done .fill{transform:scaleX(1)}body[data-option=C] .node .lb{font-size:14px}body[data-option=C] .node .ev{font-size:11.5px;gap:3px}body[data-option=C] .node .law{font-size:11.5px}body[data-option=C] .files-col{grid-column:1;grid-row:2;border:0;padding:18px 20px 60px 0;border-right:1px solid var(--hair)}body[data-option=C] .read-col{grid-column:2;grid-row:2;border:0;padding:18px 0 60px}body[data-option=C] .doc{height:265px}body[data-option=C] .doc .scroll{padding:14px 30px}body[data-option=C] .doc .name{padding-left:30px}body[data-option=C] .doc .text{font-size:16px;line-height:1.7}body[data-option=C] .result{padding:18px 24px;display:grid;grid-template-columns:1fr 1fr;gap:0 28px}body[data-option=C] .result .result-intro{grid-column:1;grid-row:1}body[data-option=C] .result .test-group{grid-column:2;grid-row:1/3}body[data-option=C] .result .result-actions{grid-column:1;grid-row:2}body[data-option=C] .result .lead{font-size:21px}body[data-option=C] .tests li{grid-template-columns:16px 1fr;font-size:13px}body[data-option=C] .tests .law{grid-column:2;font-size:11px}body[data-option=C] .actions{display:block}body[data-option=C] .actions span{display:block;margin-top:8px}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
'''
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CasePath · OPTION_TITLE</title><link rel="stylesheet" href="/assets/autonomous-workspace-v1.css"><style>STYLE</style></head><body data-option="LETTER"><header class="top"><span class="brand">CasePath</span><span class="tag">Follow the documents</span><nav class="nav"><button class="link" id="cases">Cases</button><span class="selected">Demonstration</span><button class="link" id="about">About this prototype</button></nav></header><section class="case"><div><div class="eyebrow" id="eyebrow">Recorded demonstration</div><h1 id="title">Opening the case file…</h1><div class="asks" id="asks"></div><div class="controls"><button id="pause">Pause</button><button id="skip">Skip to result</button><select id="choose" aria-label="Choose case"></select><button id="watch" hidden>Watch recorded work</button><span class="fiction">Fictional case · recorded work</span></div></div><div class="tally" id="tally"></div></section><main id="main"><section class="col files-col"><h2>From the customer</h2><ul class="files" id="files"></ul><p class="files-note">Select a file to read its recorded text.</p></section><section class="col read-col"><h2 id="reading-title">Reading now</h2><div class="role"><span class="badge" id="badge">CasePath</span><span id="what">receives the request</span></div><div id="source"></div><div class="found" id="found"></div><div id="result" hidden></div><button class="link back" id="back" hidden>Back to the result</button></section><section class="col process-col"><h2>Process <span id="stepcount"></span></h2><div class="reuse" id="reuse"></div><ol class="graph" id="graph"></ol></section><svg class="thread" id="thread" aria-hidden="true"></svg></main><footer><span id="pos">Case 1 of 9</span><span class="pips" id="pips"></span><span class="prog"><i id="prog"></i></span><span class="option-name">LETTER · OPTION_TITLE</span></footer><dialog id="dialog"><button class="link" id="close">Close</button><div id="dialogbody"></div></dialog><script>SCRIPT</script></body></html>'''
js=(root/'prototype.js').read_text()
for letter,title in [('A','Evidence desk'),('B','Document and margin'),('C','Process timeline')]:
 d=root/letter;d.mkdir(exist_ok=True)
 (d/'desk.html').write_text(html.replace('STYLE',css).replace('SCRIPT',js).replace('LETTER',letter).replace('OPTION_TITLE',title))
